"""
Alarms
"""
import xml.etree.ElementTree as Et
from builtins import object
from taf.ul.trs_e2e_fw.lib.oam.btssm.btssm_factory import BtssmFactory
from taf.ul.trs_e2e_fw.lib.oam.exceptions import UnexpectedAlarmsFoundException, AlarmNotFoundException, \
    AllAlarmOccurencesNotFoundException, AlarmShouldNotExistException
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class Alarms(object):
    """
    Alarms
    """
    def __init__(self):
        self.oam_tool = BtssmFactory().get_instance().oam_tool

    def verify_alarm(self, **kwargs):
        """
        Verify alarm
        """
        alarm_type, faultid, should_exist, occurrences, expected_alarms, timeout, filename, \
            ssh = self._get_kwargs_arguments(**kwargs)
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["timeout", "ssh", "filename", "faultid", "should_exist",
                              "occurences", "expected_alarms", "type"]}
        if faultid:
            faultid = int(faultid)
        # should_exist = bool(should_exist)
        if isinstance(should_exist, str):
            should_exist = should_exist.lower() in ('true', '1', 'yes', 'on')
        else:
            should_exist = bool(should_exist)
        occurrences = int(occurrences)

        if alarm_type.lower() == "active":
            self._verify_in_active_alarms(filename, ssh, faultid, should_exist, occurrences,
                                          expected_alarms, timeout, **kwargs)
        else:
            Exception("Alarm type not found")

    def _get_kwargs_arguments(self, **kwargs):
        alarm_type = kwargs.get("type", "active")
        faultid = kwargs.get("faultid", None)
        should_exist = kwargs.get("should_exist", True)
        occurrences = kwargs.get("occurrences", 1)
        expected_alarms = kwargs.get("expected_alarms", None)
        timeout = kwargs.get("timeout", "15min")
        filename = kwargs.get("target_filename", None)
        ssh = kwargs.get("ssh", "toor4nsn:oZPS0POrRieRtu")
        return alarm_type, faultid, should_exist, occurrences, expected_alarms, timeout, \
            filename, ssh

    def _verify_in_active_alarms(self, filename, ssh, given_faultid, should_exist, occurrences,
                                 expected_alarms, timeout, **kwargs):
        active_alarms_log_file = self.oam_tool.upload_bts_alarms_file(filename=filename, ssh=ssh,
                                                                      timeout=timeout, **kwargs)
        found_occurences, faultid_list = self._parse_for_alarms(active_alarms_log_file,
                                                                given_faultid, expected_alarms)
        unexpected_alarms = self._get_unexpected_alarms(faultid_list, given_faultid,
                                                        expected_alarms)
        self._raise_exceptions(given_faultid, should_exist, found_occurences, occurrences,
                               unexpected_alarms)

    def _parse_for_alarms(self, alarms_log_file, given_fault_id, expected_alarms):
        tree = Et.parse(alarms_log_file)
        faultid_xpath = ".//AlarmInformation/_alarmNumber"

        root = tree.getroot()
        faultid_list = []
        found_occurences = 0

        for item in root.findall(faultid_xpath):
            faultid_list.append(item.text)
            if item.text == given_fault_id:
                found_occurences += 1

        return found_occurences, faultid_list

    def _get_unexpected_alarms(self, alarm_list, given_faultid, expected_alarms):
        unexpected_alarms = []
        logger.info("expected_alarms {} type {}".format(expected_alarms, type(expected_alarms)))
        if expected_alarms is not None:
            if given_faultid is not None:
                expected_alarms.append(given_faultid)
        for alarm in alarm_list:
            if alarm not in expected_alarms:
                unexpected_alarms.append(alarm)
        return unexpected_alarms

    def _raise_exceptions(self, faultid, should_exist, found_occurences, req_occurrences,
                          unexpected_alarms):
        if len(unexpected_alarms) > 0:
            raise UnexpectedAlarmsFoundException('Alarms {}'.format(unexpected_alarms))

        if faultid is not None:
            if should_exist is False:
                if found_occurences > 0:
                    raise AlarmShouldNotExistException('Alarms {}'.format(faultid))
            else:
                if found_occurences == 0:
                    raise AlarmNotFoundException
                elif found_occurences > req_occurrences:
                    raise Exception("Alarm occured more than expected")
                elif found_occurences < req_occurrences:
                    raise AllAlarmOccurencesNotFoundException('Expected: {}, Found: {}'
                                                              .format(req_occurrences,
                                                                      found_occurences))
